import base64

b64 = """"""

# Pad to multiple of 4
padding = 4 - len(b64) % 4
if padding != 4:
    b64 += "=" * padding

print(f"Data length: {len(b64)}")

with open("C:/Users/kidis/OneDrive/Desktop/fundanmental/pharma-ims/apps/web/public/logo.jpg", "wb") as f:
    f.write(base64.b64decode(b64))
print("Logo saved")
